import gurobipy as gp
from gurobipy import GRB
shelves = []
capacities = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'ShelfID' in v and 'Capacity' in v:
        shelf = v['ShelfID']
        shelves.append(shelf)
        capacities[shelf] = float(v['Capacity'])
products = []
values = {}
weights = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'ProductName' in v and 'Value' in v and ('Weight' in v):
        pname = v['ProductName']
        products.append(pname)
        values[pname] = float(v['Value'])
        weights[pname] = float(v['Weight'])
if len(shelves) != 10:
    raise ValueError(f'Expected 10 shelves, got {len(shelves)}')
if len(products) != 20:
    raise ValueError(f'Expected 20 products, got {len(products)}')
for s in shelves:
    if s not in capacities:
        raise ValueError(f'Missing capacity for shelf {s}')
for p in products:
    if p not in values or p not in weights:
        raise ValueError(f'Missing value or weight for product {p}')
m = gp.Model('retail_display')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[p] * x[s, p] for s in shelves for p in products)), GRB.MAXIMIZE)
for s in shelves:
    m.addConstr(gp.quicksum((weights[p] * x[s, p] for p in products)) <= capacities[s], name=f'cap_{s}')
first_product = products[0]
m.addConstr(gp.quicksum((x[s, first_product] for s in shelves)) >= 5, name='smartphone_min')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')